-- ==========================================================================
-- Recovery Studio · Biblioteca de ejercicios v2
-- 30 ejercicios de cuerpo completo: 10 Principiante, 10 Intermedio, 10 Avanzado.
-- Incluye peso corporal, banda elástica, mancuernas, barra olímpica,
-- pesa rusa, TRX y BOSU. Prompts de imagen en inglés para generar fotos
-- de posición inicial y final.
--
-- Seguro de aplicar: solo agrega columnas nuevas y usa ON CONFLICT DO NOTHING.
-- No borra ni modifica los 181 ejercicios existentes.
-- ==========================================================================
begin;

alter table public.exercise_library
  add column if not exists secondary_muscles text not null default '',
  add column if not exists prompt_image_start text not null default '',
  add column if not exists prompt_image_end text not null default '';

insert into public.exercise_library
  (id, name, category, muscle_group, secondary_muscles, equipment, difficulty,
   description, cues, common_errors, variants, prompt_image_start, prompt_image_end, sort_order)
values
('ex-v2-01', 'Sentadilla al cajón', 'Peso corporal', 'Cuádriceps', 'Glúteo mayor, Isquiosurales, Core', 'Peso corporal / cajón', 'Principiante', 'Patrón de sentadilla guiado por un cajón para aprender el rango y la técnica.', 'De pie con los pies al ancho de cadera, lleva la cadera atrás y desciende hasta tocar el cajón con los glúteos, manteniendo el pecho alto y las rodillas alineadas con los pies. Inspira al bajar y exhala al empujar el suelo para subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright with the back to a knee-height plyo box, feet shoulder-width apart, toes slightly out, arms extended forward at shoulder height, neutral spine, knees straight, box directly behind the hips.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete sitting on the knee-height plyo box in a deep squat, hips back and down, thighs parallel to the floor, knees tracking over the toes, chest tall, arms extended forward, feet flat on the floor, same box position and same side-angle view.', 0),
('ex-v2-02', 'Puente de glúteo a una pierna', 'Peso corporal', 'Glúteo mayor', 'Isquiosurales, Core, Estabilizadores de cadera', 'Peso corporal / colchoneta', 'Principiante', 'Extensión de cadera unilateral para fortalecer glúteo e isquiosurales.', 'Acostado boca arriba con un pie apoyado y la otra pierna extendida, eleva la cadera hasta formar una línea recta entre hombro, cadera y rodilla, sin arquear la espalda. Exhala al subir y baja con control.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete lying supine on a mat, right foot flat on the floor with the knee bent about 90 degrees, left leg extended straight and lifted slightly off the floor, arms alongside the body with palms down, pelvis neutral on the mat.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete lying supine on a mat with the hips lifted so shoulders, hips and right knee form a straight line, right foot flat on the floor, left leg extended in line with the torso, arms pressing into the mat, glutes contracted, same side-angle view.', 0),
('ex-v2-03', 'Remo con banda elástica sentado', 'Musculación', 'Dorsal ancho', 'Romboides, Trapecio medio, Bíceps', 'Banda elástica', 'Principiante', 'Remo horizontal con banda para trabajar la espalda desde una posición estable.', 'Sentado con la espalda neutra y la banda anclada al frente, tira de los codos hacia atrás y lleva los omóplatos hacia la columna sin encoger los hombros. Exhala al tirar e inspira al volver.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete seated on the floor with legs extended and a slight knee bend, back straight, holding a long elastic band anchored in front at chest height, arms extended forward, shoulders relaxed.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete seated on the floor with a straight back, pulling the elastic band toward the lower ribs, elbows driven back close to the torso, shoulder blades squeezed together, band taut, same side-angle view.', 0),
('ex-v2-04', 'Press de hombros con banda elástica', 'Musculación', 'Deltoides anterior', 'Deltoides lateral, Tríceps, Trapecio superior', 'Banda elástica', 'Principiante', 'Empuje vertical con banda para hombros y tríceps.', 'De pie sobre la banda con los codos a 90° y las manos a la altura de los hombros, empuja hacia arriba hasta extender los brazos sin arquear la espalda. Exhala al empujar y baja controlando la banda.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing on the middle of a long elastic band, feet shoulder-width apart, hands at shoulder height with elbows bent about 90 degrees and palms facing forward, band taut behind the upper arms, neutral spine.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing on the elastic band with arms extended overhead and a slight elbow bend, hands above the shoulders, band taut, ribs down, core braced, no lower-back arch, same side-angle view.', 0),
('ex-v2-05', 'Curl martillo con mancuernas', 'Musculación', 'Bíceps braquial', 'Braquial anterior, Braquiorradial, Flexores del antebrazo', 'Mancuernas', 'Principiante', 'Flexión de codo con agarre neutro para bíceps y antebrazo.', 'De pie con los brazos extendidos y las palmas enfrentadas, flexiona los codos sin mover los hombros y sube las mancuernas hasta cerca del pecho. Exhala al subir y baja lento.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright with a dumbbell in each hand, arms fully extended at the sides, palms facing each other in a neutral grip, shoulders relaxed, neutral spine.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright with elbows flexed about 90 degrees, dumbbells raised toward the shoulders with palms still facing each other, upper arms vertical and close to the torso, wrists neutral, same side-angle view.', 0),
('ex-v2-06', 'Sentadilla sumo con mancuerna', 'Musculación', 'Glúteo mayor', 'Cuádriceps, Aductores, Isquiosurales', 'Mancuerna', 'Principiante', 'Sentadilla con pies amplios y una mancuerna al pecho para enfatizar glúteos y aductores.', 'Con los pies más anchos que los hombros y las puntas hacia afuera, desciende manteniendo el torso erguido y las rodillas siguiendo la línea de los pies. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing with feet wider than shoulder-width, toes turned out about 30 degrees, holding one dumbbell vertically with both hands at chest height, elbows tucked, chest tall, knees straight.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a deep sumo squat with hips lowered between the feet, thighs near parallel to the floor, knees tracking over the turned-out toes, torso upright, dumbbell held at the chest with both hands, same side-angle view.', 0),
('ex-v2-07', 'Step-up al cajón', 'Peso corporal', 'Cuádriceps', 'Glúteo mayor, Isquiosurales, Core', 'Peso corporal / cajón', 'Principiante', 'Subida unilateral a un cajón para fuerza y estabilidad de piernas.', 'Apoya un pie completo sobre el cajón, empuja con esa pierna para subir el cuerpo y controla el descenso sin dejarte caer. Exhala al subir y mantén el tronco erguido.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing facing a knee-height plyo box, right foot placed flat on top of the box, left foot on the floor behind, torso upright, arms relaxed at the sides.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing on top of the plyo box with the right leg fully extended, left knee lifted to hip height, torso upright, arms in a natural running position, box under the right foot, same side-angle view.', 0),
('ex-v2-08', 'Remo con pesa rusa a una mano', 'Kettlebell', 'Dorsal ancho', 'Romboides, Trapecio medio, Bíceps, Core', 'Pesa rusa', 'Principiante', 'Remo unilateral con pesa rusa para espalda y estabilidad del tronco.', 'Con una rodilla y una mano apoyadas en un banco y la espalda plana, tira de la pesa hacia la cadera manteniendo el codo cerca del cuerpo. Exhala al tirar y baja con control.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete with the left knee and left hand supported on a flat bench, right foot on the floor, torso horizontal and back flat, right arm hanging straight down holding a kettlebell, shoulder blade neutral.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in the same bench-supported position, right elbow pulled back past the torso, kettlebell raised to hip height, shoulder blade retracted, back flat, no torso rotation, same side-angle view.', 0),
('ex-v2-09', 'Flexiones en pared', 'Peso corporal', 'Pectoral mayor', 'Tríceps, Deltoides anterior, Core', 'Peso corporal / pared', 'Principiante', 'Flexión de brazos de pie contra la pared, ideal para aprender el patrón de empuje.', 'Con las manos a la altura del pecho y el cuerpo en línea, flexiona los codos para acercar el pecho a la pared y empuja para volver. Inspira al acercarte y exhala al empujar.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing facing a plain white wall, hands placed on the wall at chest height slightly wider than shoulders, body in a straight line from head to heels, elbows extended, feet together.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing facing the wall with elbows flexed about 90 degrees, chest close to the wall, body still in a straight line from head to heels, heels flat, core braced, same side-angle view.', 0),
('ex-v2-10', 'Sentadilla en TRX', 'Musculación', 'Cuádriceps', 'Glúteo mayor, Isquiosurales, Core', 'TRX', 'Principiante', 'Sentadilla asistida con TRX para mejorar el equilibrio y la profundidad.', 'De pie frente al anclaje, sujeta las asas con los brazos extendidos y desciende llevando la cadera atrás mientras las asas te acompañan. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing facing a TRX suspension trainer anchored overhead, holding both handles with arms extended forward at chest height, feet shoulder-width apart, torso upright, straps taut.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a deep squat facing the TRX anchor, hips back and down, thighs near parallel to the floor, chest tall, arms extended forward holding the handles, straps taut, feet flat, same side-angle view.', 0),
('ex-v2-11', 'Zercher squat con barra', 'Musculación', 'Cuádriceps', 'Glúteo mayor, Aductores, Core, Bíceps', 'Barra olímpica', 'Intermedio', 'Sentadilla con la barra apoyada en el pliegue de los codos, que exige un tronco muy erguido y control del core.', 'Con la barra en los codos y los pies al ancho de hombros, desciende entre los talones manteniendo el pecho alto y los codos dentro de las rodillas. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright with a barbell resting in the crooks of both elbows, forearms crossed and hands clasped in front of the chest, feet shoulder-width apart, chest tall, elbows high.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a deep squat with the barbell still in the elbow crooks, hips below knee height, torso very upright, elbows inside the knees, heels flat, chest tall, same side-angle view.', 0),
('ex-v2-12', 'Good morning con barra', 'Musculación', 'Isquiosurales', 'Glúteo mayor, Erectores espinales, Core', 'Barra olímpica', 'Intermedio', 'Bisagra de cadera con barra sobre los hombros para cadena posterior.', 'Con las rodillas levemente flexionadas y la espalda neutra, lleva la cadera atrás hasta que el torso quede casi paralelo al suelo y vuelve apretando glúteos. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing with a barbell across the upper back, hands gripping the bar wider than shoulders, feet shoulder-width apart, knees slightly bent, back neutral, hips extended.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete hinged forward at the hips with the barbell on the upper back, torso nearly parallel to the floor, knees slightly bent, back flat, hips pushed back, bar over the midfoot, same side-angle view.', 0),
('ex-v2-13', 'Landmine press', 'Musculación', 'Deltoides anterior', 'Pectoral superior, Tríceps, Core', 'Barra olímpica / landmine', 'Intermedio', 'Empuje diagonal con barra anclada en el suelo, amable con el hombro.', 'De pie con la barra sujeta con una mano a la altura del hombro, empuja hacia arriba y adelante hasta extender el brazo sin rotar el tronco. Exhala al empujar y baja con control.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing in a split stance facing a landmine with one end of a barbell anchored at the floor, holding the free end with the right hand at shoulder height, elbow bent, torso upright.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in the same split stance pressing the landmine bar diagonally up and forward, right arm extended, shoulder blade upwardly rotated, torso stable, no rotation, same side-angle view.', 0),
('ex-v2-14', 'Jalón al pecho con banda', 'Musculación', 'Dorsal ancho', 'Romboides, Trapecio medio, Bíceps', 'Banda elástica', 'Intermedio', 'Jalón vertical con banda anclada en alto para trabajar la espalda.', 'De pie o arrodillado frente al anclaje, tira de las asas hacia el pecho llevando los codos hacia abajo y atrás sin encoger los hombros. Exhala al jalar y sube controlando la banda.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete kneeling facing a high anchor point, holding both ends of an elastic band with arms extended overhead, shoulders down, torso upright, band taut.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete kneeling and pulling the band down to chest level, elbows driven down and back, shoulder blades depressed and retracted, torso upright, band taut, same side-angle view.', 0),
('ex-v2-15', 'Sentadilla con banda elástica', 'Musculación', 'Cuádriceps', 'Glúteo mayor, Aductores, Core', 'Banda elástica', 'Intermedio', 'Sentadilla con banda alrededor de los muslos para activar glúteos y mejorar la alineación de rodillas.', 'Con la banda sobre las rodillas y los pies al ancho de hombros, desciende manteniendo la banda tensa y las rodillas hacia afuera. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing with feet shoulder-width apart, a loop band around both thighs just above the knees, arms extended forward at chest height, knees straight, band under tension.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a squat with hips back and down, thighs near parallel to the floor, knees pushed outward against the band, chest tall, arms forward, feet flat, same side-angle view.', 0),
('ex-v2-16', 'Sentadilla front rack con pesa rusa', 'Kettlebell', 'Cuádriceps', 'Glúteo mayor, Core, Espalda alta', 'Pesa rusa', 'Intermedio', 'Sentadilla con la pesa rusa en posición front rack para un tronco más vertical y mayor demanda de core.', 'Con la pesa apoyada en el pecho y los codos altos, desciende entre los talones manteniendo el pecho arriba. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright holding a kettlebell in the front rack position against the chest, both hands under the bell, elbows high and tucked, feet shoulder-width apart, chest tall.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a deep squat with the kettlebell still in the front rack, elbows high, torso upright, hips below knee height, heels flat, knees tracking over the toes, same side-angle view.', 0),
('ex-v2-17', 'Flexiones declinadas', 'Peso corporal', 'Pectoral mayor', 'Deltoides anterior, Tríceps, Core', 'Peso corporal / banco', 'Intermedio', 'Flexión con los pies elevados para aumentar la carga sobre pecho y hombros.', 'Con las manos en el suelo y los pies sobre un banco, baja el pecho hasta cerca del suelo manteniendo el cuerpo en línea. Inspira al bajar y exhala al empujar.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a push-up position with hands on the floor slightly wider than shoulders and both feet elevated on a flat bench, body in a straight line, elbows extended, head neutral.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a decline push-up with elbows flexed about 90 degrees, chest lowered close to the floor, hips in line with shoulders and heels, feet still on the bench, core braced, same side-angle view.', 0),
('ex-v2-18', 'Sentadilla cosaca', 'Peso corporal', 'Cuádriceps', 'Aductores, Glúteo mayor, Isquiosurales, Core', 'Peso corporal', 'Intermedio', 'Sentadilla lateral profunda que combina fuerza de piernas y movilidad de cadera.', 'Con los pies bien separados, desplaza el peso hacia una pierna y flexiona esa rodilla mientras la otra pierna queda extendida con la punta hacia arriba. Inspira al bajar y exhala al volver al centro.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing with a very wide stance, toes slightly out, arms extended forward for balance, torso upright, weight centered between both feet.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a deep cossack squat shifted over the right leg, right knee deeply flexed with the foot flat, left leg extended straight with the toes pointing up, torso upright, arms forward, hips low, same side-angle view.', 0),
('ex-v2-19', 'Press de pecho en TRX', 'Musculación', 'Pectoral mayor', 'Deltoides anterior, Tríceps, Core', 'TRX', 'Intermedio', 'Empuje horizontal en suspensión que añade demanda de core y estabilidad.', 'De frente al anclaje con las asas a la altura del pecho, inclina el cuerpo hacia adelante y flexiona los codos hasta que el pecho pase entre las manos. Inspira al bajar y exhala al empujar.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete facing away from a TRX anchor, holding both handles at chest height, body leaning forward in a straight line from head to heels, elbows bent, straps taut, feet shoulder-width apart.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in the same suspended position with elbows extended, body lowered toward the floor in a straight line, chest between the handles, straps taut, core braced, same side-angle view.', 0),
('ex-v2-20', 'Curl femoral en TRX', 'Musculación', 'Isquiosurales', 'Glúteo mayor, Core, Gastrocnemio', 'TRX', 'Intermedio', 'Flexión de rodilla en suspensión para isquiosurales y control pélvico.', 'Acostado boca arriba con los talones en las asas y la cadera elevada, flexiona las rodillas para acercar los talones a los glúteos sin dejar caer la cadera. Exhala al flexionar y baja lento.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete lying supine on the floor with both heels in the TRX foot cradles, legs extended, hips lifted slightly off the floor, arms alongside the body, body in a straight line.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete lying supine with hips lifted, knees flexed about 90 degrees pulling the heels toward the glutes, TRX straps taut, shoulders and head on the floor, hips high, same side-angle view.', 0),
('ex-v2-21', 'Barbell rollout', 'Core', 'Recto abdominal', 'Oblicuos, Transverso abdominal, Dorsal ancho, Hombros', 'Barra olímpica', 'Avanzado', 'Rodamiento con barra desde rodillas para un core anti-extensión muy exigente.', 'Arrodillado con la barra en el suelo y las manos al ancho de hombros, rueda la barra hacia adelante manteniendo la espalda neutra y el abdomen apretado, y vuelve tirando con el core. Exhala al rodar y controla la vuelta.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete kneeling on a mat holding a barbell on the floor with both hands shoulder-width apart, arms extended, back neutral, hips above the knees, core braced.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete kneeling with the barbell rolled forward, arms extended overhead in line with the torso, body in a straight line from knees to shoulders, hips not sagging, core braced, same side-angle view.', 0),
('ex-v2-22', 'Landmine row', 'Musculación', 'Dorsal ancho', 'Romboides, Trapecio medio, Bíceps, Core', 'Barra olímpica / landmine', 'Avanzado', 'Remo con barra anclada en el suelo, con un recorrido estable y gran demanda de espalda.', 'De pie frente a la barra con las rodillas semiflexionadas y la espalda neutra, tira del extremo de la barra hacia la cadera y aprieta los omóplatos. Exhala al tirar y baja con control.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing in a staggered stance over a landmine barbell, knees slightly bent, torso hinged forward with a flat back, right hand holding the end of the bar with the arm extended down.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in the same hinged stance pulling the landmine bar toward the hip, right elbow driven back past the torso, shoulder blade retracted, back flat, no torso rotation, same side-angle view.', 0),
('ex-v2-23', 'Zancada inversa con barra', 'Musculación', 'Cuádriceps', 'Glúteo mayor, Isquiosurales, Core', 'Barra olímpica', 'Avanzado', 'Zancada hacia atrás con barra sobre los hombros para fuerza unilateral y control.', 'Con la barra apoyada en la espalda alta, da un paso atrás y desciende hasta que ambas rodillas formen 90°, manteniendo el torso erguido. Inspira al bajar y exhala al empujar para volver.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright with a barbell across the upper back, hands gripping the bar, feet hip-width apart, left foot stepping back, both knees straight, torso upright.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a reverse lunge with the left knee lowered near the floor and the right knee bent about 90 degrees, torso upright, barbell stable on the upper back, front foot flat, same side-angle view.', 0),
('ex-v2-24', 'Flexiones archer', 'Peso corporal', 'Pectoral mayor', 'Tríceps, Deltoides anterior, Core', 'Peso corporal', 'Avanzado', 'Flexión unilateral asistida que aumenta la carga en un lado del pecho.', 'Con las manos más anchas que los hombros, flexiona un codo y baja hacia ese lado mientras el otro brazo se extiende, y empuja para volver al centro. Inspira al bajar y exhala al empujar.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a wide push-up position with hands wider than shoulder-width, body in a straight line, elbows extended, weight centered, head neutral.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in an archer push-up shifted over the right arm, right elbow flexed about 90 degrees, left arm extended straight to the side, chest lowered toward the right hand, hips in line, core braced, same side-angle view.', 0),
('ex-v2-25', 'Flexiones con palmada', 'Peso corporal', 'Pectoral mayor', 'Tríceps, Deltoides anterior, Core', 'Peso corporal', 'Avanzado', 'Flexión pliométrica en la que el cuerpo se impulsa para aplaudir en el aire.', 'Desde la posición de flexión, baja el pecho y empuja con fuerza para despegar las manos y dar una palmada antes de aterrizar con codos suaves. Exhala en el impulso y absorbe la caída.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a standard push-up position with hands under the shoulders, body in a straight line, elbows extended, core braced.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete airborne above the floor in a push-up position, hands separated in a clap at chest height, elbows slightly bent, body in a straight line, feet off the floor, dynamic mid-air moment, same side-angle view.', 0),
('ex-v2-26', 'Sentadilla pistol', 'Peso corporal', 'Cuádriceps', 'Glúteo mayor, Isquiosurales, Core, Estabilizadores de tobillo', 'Peso corporal', 'Avanzado', 'Sentadilla a una pierna completa, con la otra pierna extendida al frente.', 'De pie sobre una pierna, desciende controlando la rodilla y la cadera hasta llegar lo más abajo posible sin perder el equilibrio, y sube empujando el suelo. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing on the right leg, left leg extended forward with the foot off the floor, arms extended forward for balance, right knee straight, torso upright.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a full pistol squat on the right leg, right hip below the knee, right foot flat on the floor, left leg extended straight forward, arms forward, torso upright, core braced, same side-angle view.', 0),
('ex-v2-27', 'TRX fallout', 'Core', 'Recto abdominal', 'Oblicuos, Transverso abdominal, Dorsal ancho, Hombros', 'TRX', 'Avanzado', 'Ejercicio anti-extensión en suspensión para un core profundo y estable.', 'De pie de espaldas al anclaje con las asas en las manos, inclina el cuerpo hacia adelante con los brazos extendidos y la cadera alineada, y vuelve tirando del core. Exhala al inclinarte y controla la vuelta.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing facing away from a TRX anchor, holding both handles at shoulder height with arms extended forward, body in a straight line leaning slightly forward, hips extended, straps taut.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete with arms extended overhead and body inclined forward in a straight line from head to heels, hips not sagging, shoulders flexed, straps taut, core strongly braced, same side-angle view.', 0),
('ex-v2-28', 'Sentadilla búlgara en BOSU', 'Musculación', 'Cuádriceps', 'Glúteo mayor, Isquiosurales, Core, Estabilizadores de tobillo', 'BOSU', 'Avanzado', 'Sentadilla búlgara con el pie trasero sobre un BOSU, que suma inestabilidad y control unilateral.', 'Con el pie delantero firme y el empeine trasero sobre el BOSU, desciende flexionando la rodilla delantera y mantén el torso erguido. Inspira al bajar y exhala al subir.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing in a split stance with the right foot forward on the floor and the left instep resting on top of a BOSU dome behind, torso upright, hands on the hips, knees straight.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a Bulgarian split squat with the right knee bent about 90 degrees, left knee lowered toward the floor, torso upright, right foot flat, left instep stable on the BOSU dome, same side-angle view.', 0),
('ex-v2-29', 'Burpee con BOSU', 'Peso corporal', 'Cuerpo completo', 'Pectoral, Cuádriceps, Glúteo, Tríceps, Core', 'BOSU', 'Avanzado', 'Burpee con apoyo de manos sobre el BOSU que combina sentadilla, plancha y salto.', 'Desde de pie frente al BOSU, apoya las manos y lleva los pies atrás a plancha, vuelve a recogerlos y salta con los brazos arriba. Exhala en el salto y mantén el core firme en plancha.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing upright facing a BOSU dome on the floor, feet shoulder-width apart, arms at the sides, knees slightly bent, ready to squat.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete jumping vertically in front of the BOSU dome, arms extended overhead, body fully extended, feet off the floor, knees slightly bent, dynamic mid-air moment, same side-angle view.', 0),
('ex-v2-30', 'Man maker con mancuernas', 'Musculación', 'Cuerpo completo', 'Hombros, Espalda, Pectoral, Tríceps, Glúteo, Core', 'Mancuernas', 'Avanzado', 'Secuencia completa con mancuernas que encadena sentadilla, flexión, remo y press.', 'Desde la posición de plancha con las manos en las mancuernas, haz una flexión, un remo por lado, salta a sentadilla y termina con un press sobre la cabeza. Exhala en cada empuje y mantén la espalda neutra.', '', '', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete in a plank position with both hands gripping dumbbells on the floor, arms extended, body in a straight line, feet shoulder-width apart, core braced.', 'Clean 3D anatomical fitness illustration on a pure white background, active muscles highlighted in soft red, studio lighting, side-angle view, photorealistic proportions, no text, no logos. Athlete standing with both dumbbells pressed overhead, arms extended, legs straight, torso upright, feet shoulder-width apart, core braced, same side-angle view.', 0)
on conflict (id) do nothing;

commit;
